const dns = require('dns').promises;
const crypto = require('crypto');

/**
 * Generates a random unique verification token.
 * @returns {string} Hex string token
 */
const generateVerificationToken = () => {
  return crypto.randomBytes(32).toString('hex');
};

/**
 * Fetches TXT records for the domain and checks if the token exists.
 * @param {string} domainName 
 * @param {string} token 
 * @returns {Promise<boolean>}
 */
const verifyDomainDns = async (domainName, token) => {
  try {
    // resolveTxt returns an array of arrays (chunks of text)
    const records = await dns.resolveTxt(domainName);

    // Flatten chunks and look for the token
    const flatRecords = records.map(chunk => chunk.join(''));

    // Check if any record equals the token or contains it
    return flatRecords.some(record => record.includes(token));
  } catch (error) {
    // Domain not found or no TXT records
    return false;
  }
};

/**
 * Fetches MX records to see if they exist.
 * Checks for actual MX records on the domain.
 * @param {string} domainName 
 * @returns {Promise<boolean>}
 */
const checkMxRecord = async (domainName) => {
  try {
    const records = await dns.resolveMx(domainName);
    return records && records.length > 0;
  } catch (error) {
    return false;
  }
};

/**
 * Generates RSA 2048-bit key pair for DKIM.
 * @returns {{privateKey: string, publicKey: string}}
 */
const generateDkimKeys = () => {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem'
    }
  });

  return { privateKey, publicKey };
};

module.exports = {
  generateVerificationToken,
  verifyDomainDns,
  checkMxRecord,
  generateDkimKeys
};

import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

// Fix for missing JSX definitions in the environment
declare global {
  namespace JSX {
    interface IntrinsicElements {
      [elemName: string]: any;
    }
  }
}

// --- TYPES ---
interface User {
  email: string;
  company_name?: string;
  token?: string;
  role: 'client' | 'mailbox';
}

interface Domain {
  _id: string;
  name: string;
  verification_token: string;
  is_verified: boolean;
  mx_status: string;
  dkim_public_key?: string;
}

interface Mailbox {
  _id: string;
  email: string;
  domain_id: { _id: string; name: string } | string;
}

interface EmailMessage {
  _id: string;
  from: string;
  to: string;
  subject: string;
  text_body: string;
  html_body: string;
  folder: 'inbox' | 'sent';
  created_at: string;
}

// --- API CONFIG ---
const api = axios.create({
  baseURL: 'http://localhost:4000/api',
});

// Add token to requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('smtp_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// --- COMPONENTS ---

