// 2. AUTH VIEW
const AuthView = ({ 
  role, 
  onSuccess, 
  onBack 
}: { 
  role: 'client' | 'mailbox', 
  onSuccess: (user: User) => void, 
  onBack: () => void 
}) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
