export default function App() {
  const [view, setView] = useState<'landing' | 'client-login' | 'webmail-login' | 'client-dashboard' | 'webmail-dashboard'>('landing');
  const [user, setUser] = useState<User | null>(null);

  // Check auth on load
  useEffect(() => {
    const token = localStorage.getItem('smtp_token');
    const role = localStorage.getItem('smtp_role');
    // Note: In a real app we would decode the token to get the user or verify via API.
    // For this prototype, we will just clear if no token.
    if (!token) {
      setView('landing');
    }
  }, []);

  const handleLoginSuccess = (userData: User) => {
    setUser(userData);
    localStorage.setItem('smtp_role', userData.role);
    setView(userData.role === 'client' ? 'client-dashboard' : 'webmail-dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('smtp_token');
    localStorage.removeItem('smtp_role');
    setUser(null);
    setView('landing');
  };

  return (
    <>
      {view === 'landing' && <LandingView onNavigate={(v) => setView(v as any)} />}

      {view === 'client-login' && (
        <AuthView role="client" onSuccess={handleLoginSuccess} onBack={() => setView('landing')} />
      )}

      {view === 'webmail-login' && (
        <AuthView role="mailbox" onSuccess={handleLoginSuccess} onBack={() => setView('landing')} />
      )}

      {view === 'client-dashboard' && user && (
        <ClientDashboard user={user} onLogout={handleLogout} />
      )}

      {view === 'webmail-dashboard' && user && (
        <WebmailView user={user} onLogout={handleLogout} />
      )}
    </>
  );
}

const jwt = require('jsonwebtoken');

const authenticateClient = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Access Denied: No Token Provided' });

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET || 'secret');
    if (!verified.client_id) return res.status(403).json({ error: 'Access Denied: Invalid Token Type' });
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).json({ error: 'Invalid Token' });
  }
};

const authenticateWebmail = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Access Denied: No Token Provided' });

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET || 'secret');
    if (!verified.mailbox_id) return res.status(403).json({ error: 'Access Denied: Invalid Token Type' });
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).json({ error: 'Invalid Token' });
  }
};

module.exports = { authenticateClient, authenticateWebmail };

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Client = require('../models/Client');
const logger = require('../config/logger');

// Register Client
router.post('/register', async (req, res) => {
  try {
    const { email, password, company_name } = req.body;

    const existing = await Client.findOne({ email });
    if (existing) return res.status(400).json({ error: 'Email already registered' });

    const salt = await bcrypt.genSalt(10);
    const password_hash = await bcrypt.hash(password, salt);

    const client = await Client.create({
      email,
      password_hash,
      company_name
    });

    res.status(201).json({ message: 'Client registered successfully', client_id: client._id });
  } catch (err) {
    logger.error('Registration Error:', err);
    res.status(500).json({ error: 'Registration failed' });
  }
});

// Login Client
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const client = await Client.findOne({ email });
    if (!client) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, client.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ client_id: client._id }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
    res.json({ token, client: { email: client.email, company_name: client.company_name } });
  } catch (err) {
    logger.error('Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const Domain = require('../models/Domain');
const Mailbox = require('../models/Mailbox');
const domainService = require('../services/domain.service');
const { authenticateClient } = require('../middleware/auth');
const logger = require('../config/logger');

// Add Domain
router.post('/', authenticateClient, async (req, res) => {
  try {
    const { name } = req.body;
    if (!name) return res.status(400).json({ error: 'Domain name required' });

    const token = domainService.generateVerificationToken();

    const domain = await Domain.create({
      client_id: req.user.client_id,
      name: name.toLowerCase(),
      verification_token: token
    });

    res.status(201).json(domain);
  } catch (err) {
    logger.error('Add Domain Error:', err);
    if (err.code === 11000) return res.status(400).json({ error: 'Domain already registered' });
    res.status(500).json({ error: 'Failed to add domain' });
  }
});

// Verify Domain
router.post('/:id/verify', authenticateClient, async (req, res) => {
  try {
    const domain = await Domain.findOne({ _id: req.params.id, client_id: req.user.client_id });
    if (!domain) return res.status(404).json({ error: 'Domain not found' });

    const isVerified = await domainService.verifyDomainDns(domain.name, domain.verification_token);

    if (isVerified) {
      const keys = domainService.generateDkimKeys();
      const mxExists = await domainService.checkMxRecord(domain.name);

      domain.is_verified = true;
      domain.mx_status = mxExists ? 'active' : 'pending';
      domain.dkim_private_key = keys.privateKey;
      domain.dkim_public_key = keys.publicKey;
      await domain.save();

      res.json({ message: 'Domain verified', domain });
    } else {
      res.status(400).json({ error: 'DNS verification failed. Token not found in TXT records.' });
    }
  } catch (err) {
    logger.error('Verify Domain Error:', err);
    res.status(500).json({ error: 'Verification error' });
  }
});

// List Domains
router.get('/', authenticateClient, async (req, res) => {
  try {
    const domains = await Domain.find({ client_id: req.user.client_id });
    res.json(domains);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch domains' });
  }
});

// Create Mailbox for Domain
router.post('/:id/mailboxes', authenticateClient, async (req, res) => {
  try {
    const { email, password, quota_bytes } = req.body;

    // Verify domain ownership
    const domain = await Domain.findOne({ _id: req.params.id, client_id: req.user.client_id });
    if (!domain) return res.status(404).json({ error: 'Domain not found' });
    if (!domain.is_verified) return res.status(400).json({ error: 'Domain not verified' });

    // Check if email ends with domain.name
    if (!email.toLowerCase().endsWith(`@${domain.name}`)) {
      return res.status(400).json({ error: `Email must end with @${domain.name}` });
    }

    const salt = await bcrypt.genSalt(10);
    const password_hash = await bcrypt.hash(password, salt);

    const mailbox = await Mailbox.create({
      domain_id: domain._id,
      email,
      password_hash,
      quota_bytes: quota_bytes || 1073741824
    });

    res.status(201).json({ message: 'Mailbox created', mailbox_id: mailbox._id });
  } catch (err) {
    logger.error('Create Mailbox Error:', err);
    if (err.code === 11000) return res.status(400).json({ error: 'Email already exists' });
    res.status(500).json({ error: 'Failed to create mailbox' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const Mailbox = require('../models/Mailbox');
const Domain = require('../models/Domain');
const { authenticateClient } = require('../middleware/auth');

// List Mailboxes
router.get('/', authenticateClient, async (req, res) => {
  try {
    // Find all domains owned by client
    const domains = await Domain.find({ client_id: req.user.client_id }).select('_id');
    const domainIds = domains.map(d => d._id);

    const mailboxes = await Mailbox.find({ domain_id: { $in: domainIds } })
      .populate('domain_id', 'name')
      .sort({ created_at: -1 });

    res.json(mailboxes);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch mailboxes' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const { authenticateWebmail } = require('../middleware/auth');
const logger = require('../config/logger');

// Webmail Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
    res.json({ token, email: mailbox.email });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Webmail Messages
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const messages = await EmailMessage.find({ mailbox_id: req.user.mailbox_id })
      .sort({ created_at: -1 })
      .limit(100);
    res.json(messages);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

module.exports = router;

require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const helmet = require('helmet');

const smtpServer = require('./src/smtp/server');
const logger = require('./src/config/logger');
const seedDatabase = require('./src/config/seed');

// Routes Imports
const clientAuthRoutes = require('./src/routes/clientAuth');
const domainRoutes = require('./src/routes/domains');
const mailboxRoutes = require('./src/routes/mailboxes');
const webmailRoutes = require('./src/routes/webmail');

const app = express();

// Security & Middleware
app.use(helmet());

// Robust CORS Configuration
const corsOptions = {
  origin: 'https://smtp.eeina.com', // Explicitly allow your frontend domain
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'], // Allowed methods
  allowedHeaders: ['Content-Type', 'Authorization'], // Allowed headers
  credentials: true, // Enable if you ever need cookies, good practice
  optionsSuccessStatus: 204
};

// Apply CORS middleware
app.use(cors(corsOptions));
// Explicitly handle OPTIONS preflight requests for all routes just in case
app.options('*', cors(corsOptions));

app.use(express.json());

// Database Connection
mongoose.connect(process.env.MONGO_URI)
  .then(async () => {
    logger.info('MongoDB Connected');
    await seedDatabase();
  })
  .catch(err => logger.error('MongoDB Connection Error:', err));

// --- MOUNT ROUTES ---
app.use('/api/auth', clientAuthRoutes);
app.use('/api/domains', domainRoutes);
app.use('/api/mailboxes', mailboxRoutes);
app.use('/api/webmail', webmailRoutes);

// Start Servers
const PORT = process.env.PORT || 4000;
const SMTP_PORT = process.env.SMTP_PORT || 2525;
const SUBMISSION_PORT = process.env.SUBMISSION_PORT || 5870;

app.listen(PORT, () => {
  logger.info(`Express Server running on port ${PORT}`);
});

smtpServer.start(SMTP_PORT, SUBMISSION_PORT);

import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

// --- TYPES ---
interface User {
  email: string;
  company_name?: string;
  token?: string;
  role: 'client' | 'mailbox';
}

interface Domain {
  _id: string;
  name: string;
  verification_token: string;
  is_verified: boolean;
  mx_status: string;
  dkim_public_key?: string;
}

interface Mailbox {
  _id: string;
  email: string;
  domain_id: { _id: string; name: string } | string;
}

interface EmailMessage {
  _id: string;
  from: string;
  to: string;
  subject: string;
  text_body: string;
  html_body: string;
  folder: 'inbox' | 'sent';
  created_at: string;
}

// --- API CONFIG ---
const api = axios.create({
  // Point to the dedicated backend API domain
  baseURL: 'https://mail-api.eeina.com',
});

// Add token to requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('smtp_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

