                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Mailboxes Column */}
          <div className="bg-white shadow rounded-lg p-6 h-fit">
            <h3 className="text-lg font-medium text-gray-900 mb-4">All Mailboxes</h3>
