import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

// Workaround for missing JSX.IntrinsicElements definitions
declare global {
  namespace JSX {
    interface IntrinsicElements {
      [elemName: string]: any;
    }
  }
}

// --- TYPES ---
interface User {
  email: string;
  company_name?: string;
  token?: string;
  role: 'client' | 'mailbox';
}

interface Domain {
  _id: string;
  name: string;
  verification_token: string;
  is_verified: boolean;
  mx_status: string;
  dkim_public_key?: string;
}

interface Mailbox {
  _id: string;
  email: string;
  domain_id: { _id: string; name: string } | string;
}

interface EmailMessage {
  _id: string;
  from: string;
  to: string;
  subject: string;
  text_body: string;
  html_body: string;
  folder: 'inbox' | 'sent';
  created_at: string;
}

// --- API CONFIG ---
const api = axios.create({
  // Point to the dedicated backend API domain
  baseURL: 'https://mail-api.eeina.com',
});

// Add token to requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('smtp_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

