              </div>

              <div className="space-y-4">
                {domains.length === 0 && <p className="text-gray-500 text-sm italic">No domains added yet.</p>}
                {domains.map(domain => (
                  <div key={domain._id} className="border border-gray-200 rounded-md p-4">
