                {user.company_name}
              </span>
            </div>
            <div className="flex items-center">
              <span className="text-gray-500 mr-4">{user.email}</span>
              <button onClick={onLogout} className="text-red-600 hover:text-red-800 font-medium text-sm">Logout</button>
            </div>
          </div>
        </div>
      </nav>

