const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const { authenticateWebmail } = require('../middleware/auth');
const logger = require('../config/logger');

// Webmail Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
    res.json({ token, email: mailbox.email });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Webmail Messages
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const messages = await EmailMessage.find({ mailbox_id: req.user.mailbox_id })
      .sort({ created_at: -1 })
      .limit(100);
    res.json(messages);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// Send Email
router.post('/send', authenticateWebmail, async (req, res) => {
  try {
    const { to, subject, body } = req.body;

    if (!to) return res.status(400).json({ error: 'Recipient required' });

    const senderMailboxId = req.user.mailbox_id;
    const senderEmail = req.user.email;

    // 1. Save to Sender's Sent Folder
    // We convert newlines to <br> for basic HTML display compatibility
    const htmlContent = body ? body.replace(/\n/g, '<br>') : '';

    await EmailMessage.create({
      mailbox_id: senderMailboxId,
      direction: 'outbound',
      from: senderEmail,
      to,
      subject: subject || '',
      text_body: body || '',
      html_body: `<div style="font-family: sans-serif;">${htmlContent}</div>`,
      folder: 'sent',
      is_read: true
    });

    // 2. Local Delivery Logic
    // Check if recipients are local users and deliver to their Inbox
    const recipients = to.split(/[;,]+/).map(r => r.trim()).filter(r => r);

    for (const recipientEmail of recipients) {
      const recipientMailbox = await Mailbox.findOne({ email: recipientEmail });

      if (recipientMailbox) {
        await EmailMessage.create({
          mailbox_id: recipientMailbox._id,
          direction: 'inbound',
          from: senderEmail,
          to: recipientEmail,
          subject: subject || '',
          text_body: body || '',
          html_body: `<div style="font-family: sans-serif;">${htmlContent}</div>`,
          folder: 'inbox',
          is_read: false
        });
        logger.info(`Internal Delivery: ${senderEmail} -> ${recipientEmail}`);
      } else {
        // Logic for external relay (e.g., via Relay Host or DNS/MX resolution) would go here.
        // For now, we only log it.
        logger.info(`External Delivery Queued (Not Implemented): ${recipientEmail}`);
      }
    }

    res.json({ message: 'Email sent successfully' });
  } catch (err) {
    logger.error('Send Error:', err);
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = router;

import React, { useState, useEffect, useRef } from 'react';
import api from '../api';
import { User, EmailMessage } from '../types';
import Spinner from '../components/Spinner';

const WebmailView = ({ user, onLogout }: { user: User, onLogout: () => void }) => {
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [selectedMsg, setSelectedMsg] = useState<EmailMessage | null>(null);
  const [view, setView] = useState<'inbox' | 'sent'>('inbox');

  // Compose State
  const [showCompose, setShowCompose] = useState(false);
  const [composeTo, setComposeTo] = useState('');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');
  const [sending, setSending] = useState(false);

  const fetchMessages = async () => {
    try {
      const res = await api.get('/api/webmail/messages');
      setMessages(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchMessages();
    const int = setInterval(fetchMessages, 10000); // Poll every 10s
    return () => clearInterval(int);
  }, []);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    setSending(true);
    try {
      await api.post('/api/webmail/send', {
        to: composeTo,
        subject: composeSubject,
        body: composeBody
      });

      // Reset and close
      setShowCompose(false);
      setComposeTo('');
      setComposeSubject('');
      setComposeBody('');

      // Refresh list
      await fetchMessages();
      if (view === 'sent') {
         // Force update if viewing sent
      }
      alert('Message Sent');
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to send message');
    } finally {
      setSending(false);
    }
  };

  const filtered = messages.filter(m => m.folder === view);

  // Safe HTML renderer using iframe
  const SafeHtml = ({ html }: { html: string }) => {
    const iframeRef = useRef<HTMLIFrameElement>(null);
    useEffect(() => {
      if (iframeRef.current) {
        const doc = iframeRef.current.contentDocument;
        if (doc) {
          doc.open();
          doc.write(html || '<div style="font-family:sans-serif;color:#666;">No content</div>');
          doc.close();
        }
      }
    }, [html]);
    return <iframe ref={iframeRef} title="email-body" className="w-full h-full border-0" />;
  };

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden relative">
      {/* Sidebar */}
      <div className="w-64 bg-slate-800 flex flex-col flex-shrink-0 text-white">
        <div className="p-4 border-b border-slate-700">
          <h1 className="text-xl font-bold">Webmail</h1>
          <p className="text-xs text-slate-400 mt-1 truncate">{user.email}</p>
        </div>

        <div className="p-4">
          <button 
            onClick={() => setShowCompose(true)}
            className="w-full flex items-center justify-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
              <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
            </svg>
            Compose
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          <button 
            onClick={() => { setView('inbox'); setSelectedMsg(null); }}
            className={`w-full text-left px-3 py-2 rounded-md text-sm font-medium flex justify-between ${view === 'inbox' ? 'bg-slate-700 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
          >
            <span>Inbox</span>
            {/* Simple count badge could go here */}
          </button>
          <button 
            onClick={() => { setView('sent'); setSelectedMsg(null); }}
            className={`w-full text-left px-3 py-2 rounded-md text-sm font-medium ${view === 'sent' ? 'bg-slate-700 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
          >
