const dns = require('dns').promises;
const crypto = require('crypto');

/**
 * Generates a random unique verification token.
 * @returns {string} Hex string token
 */
const generateVerificationToken = () => {
  return crypto.randomBytes(32).toString('hex');
};

/**
 * Fetches TXT records for the domain and checks if the token exists.
 * @param {string} domainName 
 * @param {string} token 
 * @returns {Promise<boolean>}
 */
const verifyDomainDns = async (domainName, token) => {
  try {
    // resolveTxt returns an array of arrays (chunks of text)
    const records = await dns.resolveTxt(domainName);

    // Flatten chunks and look for the token
    const flatRecords = records.map(chunk => chunk.join(''));

    // Check if any record equals the token or contains it
    return flatRecords.some(record => record.includes(token));
  } catch (error) {
    // Domain not found or no TXT records
    return false;
  }
};

/**
 * Fetches MX records to see if they exist.
 * Checks for actual MX records on the domain.
 * @param {string} domainName 
 * @returns {Promise<boolean>}
 */
const checkMxRecord = async (domainName) => {
  try {
    const records = await dns.resolveMx(domainName);
    return records && records.length > 0;
  } catch (error) {
    return false;
  }
};

/**
 * Generates RSA 2048-bit key pair for DKIM.
 * @returns {{privateKey: string, publicKey: string}}
 */
const generateDkimKeys = () => {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem'
    }
  });

  return { privateKey, publicKey };
};

/**
 * Checks detailed status of all required DNS records
 * @param {string} domainName
 * @param {string} token
 */
const getDnsStatus = async (domainName, token) => {
  const status = {
    verification: false,
    a_record: false,
    mx: false,
    spf: false,
    dmarc: false
  };

  try {
    // 1. Root TXT (Verification & SPF)
    // We catch errors individually to allow partial success
    let txtRecords = [];
    try {
      txtRecords = await dns.resolveTxt(domainName);
    } catch (e) { /* ignore */ }

    const flatTxt = txtRecords.map(c => c.join(''));
    status.verification = flatTxt.some(r => r.includes(token));
    status.spf = flatTxt.some(r => r.toLowerCase().includes('v=spf1'));

    // 2. A Record (mail.domain)
    try {
      const aRecords = await dns.resolve4(`mail.${domainName}`);
      status.a_record = aRecords.length > 0;
    } catch (e) { /* ignore */ }

    // 3. MX Record
    try {
      const mxRecords = await dns.resolveMx(domainName);
      // Valid if MX records exist. Ideally should point to mail.domainName
      // We check if any exchange contains 'mail.' or matches the A-record host
      status.mx = mxRecords.length > 0 && mxRecords.some(r => r.exchange && r.exchange.includes('mail.'));
    } catch (e) { /* ignore */ }

    // 4. DMARC (_dmarc.domain)
    try {
      const dmarcRecords = await dns.resolveTxt(`_dmarc.${domainName}`);
      const flatDmarc = dmarcRecords.map(c => c.join(''));
      status.dmarc = flatDmarc.some(r => r.toLowerCase().includes('v=dmarc1'));
    } catch (e) { /* ignore */ }

  } catch (err) {
    // Global failure
  }

  return status;
};

module.exports = {
  generateVerificationToken,
  verifyDomainDns,
  checkMxRecord,
  generateDkimKeys,
  getDnsStatus
};

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const Domain = require('../models/Domain');
const Mailbox = require('../models/Mailbox');
const domainService = require('../services/domain.service');
const { authenticateClient } = require('../middleware/auth');
const logger = require('../config/logger');

// Add Domain
router.post('/', authenticateClient, async (req, res) => {
  try {
    const { name } = req.body;
    if (!name) return res.status(400).json({ error: 'Domain name required' });

    const token = domainService.generateVerificationToken();

    const domain = await Domain.create({
      client_id: req.user.client_id,
      name: name.toLowerCase(),
      verification_token: token
    });

    res.status(201).json(domain);
  } catch (err) {
    logger.error('Add Domain Error:', err);
    if (err.code === 11000) return res.status(400).json({ error: 'Domain already registered' });
    res.status(500).json({ error: 'Failed to add domain' });
  }
});

// Verify Domain
router.post('/:id/verify', authenticateClient, async (req, res) => {
  try {
    const domain = await Domain.findOne({ _id: req.params.id, client_id: req.user.client_id });
    if (!domain) return res.status(404).json({ error: 'Domain not found' });

    const isVerified = await domainService.verifyDomainDns(domain.name, domain.verification_token);

    if (isVerified) {
      const keys = domainService.generateDkimKeys();
      const mxExists = await domainService.checkMxRecord(domain.name);

      domain.is_verified = true;
      domain.mx_status = mxExists ? 'active' : 'pending';
      domain.dkim_private_key = keys.privateKey;
      domain.dkim_public_key = keys.publicKey;
      await domain.save();

      res.json({ message: 'Domain verified', domain });
    } else {
      res.status(400).json({ error: 'DNS verification failed. Token not found in TXT records.' });
    }
  } catch (err) {
    logger.error('Verify Domain Error:', err);
    res.status(500).json({ error: 'Verification error' });
  }
});

// Check DNS Status
router.get('/:id/dns', authenticateClient, async (req, res) => {
  try {
    const domain = await Domain.findOne({ _id: req.params.id, client_id: req.user.client_id });
    if (!domain) return res.status(404).json({ error: 'Domain not found' });

    const status = await domainService.getDnsStatus(domain.name, domain.verification_token);
    res.json(status);
  } catch (err) {
    logger.error('DNS Status Error:', err);
    res.status(500).json({ error: 'Failed to check DNS status' });
  }
});

// List Domains
router.get('/', authenticateClient, async (req, res) => {
  try {
    const domains = await Domain.find({ client_id: req.user.client_id });
    res.json(domains);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch domains' });
  }
});

// Create Mailbox for Domain
router.post('/:id/mailboxes', authenticateClient, async (req, res) => {
  try {
    const { email, password, quota_bytes } = req.body;

    // Verify domain ownership
    const domain = await Domain.findOne({ _id: req.params.id, client_id: req.user.client_id });
    if (!domain) return res.status(404).json({ error: 'Domain not found' });
    if (!domain.is_verified) return res.status(400).json({ error: 'Domain not verified' });

    // Check if email ends with domain.name
    if (!email.toLowerCase().endsWith(`@${domain.name}`)) {
      return res.status(400).json({ error: `Email must end with @${domain.name}` });
    }

    const salt = await bcrypt.genSalt(10);
    const password_hash = await bcrypt.hash(password, salt);

    const mailbox = await Mailbox.create({
      domain_id: domain._id,
      email,
      password_hash,
      quota_bytes: quota_bytes || 1073741824
    });

    res.status(201).json({ message: 'Mailbox created', mailbox_id: mailbox._id });
  } catch (err) {
    logger.error('Create Mailbox Error:', err);
    if (err.code === 11000) return res.status(400).json({ error: 'Email already exists' });
    res.status(500).json({ error: 'Failed to create mailbox' });
  }
});

module.exports = router;

