const mongoose = require('mongoose');

const systemLogSchema = new mongoose.Schema({
  level: { type: String, required: true },
  message: { type: String, required: true },
  meta: { type: mongoose.Schema.Types.Mixed },
  timestamp: { type: Date, default: Date.now }
}, { 
  capped: { size: 5242880, max: 1000 } // Cap at 5MB or 1000 entries
});

module.exports = mongoose.model('SystemLog', systemLogSchema);

const winston = require('winston');
const Transport = require('winston-transport');

// Custom Transport to save logs to MongoDB
class MongoTransport extends Transport {
  constructor(opts) {
    super(opts);
  }

  log(info, callback) {
    setImmediate(() => {
      this.emit('logged', info);
    });

    try {
      // Lazy load model to ensure mongoose connection exists
      const SystemLog = require('../models/SystemLog');

      // Clean up meta to ensure circular structures don't break insert
      const { level, message, ...meta } = info;

      SystemLog.create({
        level,
        message,
        meta
      }).catch(err => {
        // Fallback to console if DB fails, to avoid infinite loop
        console.error('Failed to write log to DB:', err.message);
      });

    } catch(e) {
      console.error("MongoTransport error", e);
    }

    callback();
  }
}

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'smtp-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new MongoTransport() // Add our custom transport
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    ),
  }));
} else {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

module.exports = logger;

const express = require('express');
const router = express.Router();
const SystemLog = require('../models/SystemLog');
const { authenticateClient } = require('../middleware/auth');

// Get recent logs (Admin only)
router.get('/logs', authenticateClient, async (req, res) => {
  try {
    const logs = await SystemLog.find()
      .sort({ timestamp: -1 })
      .limit(100);
    res.json(logs);
  } catch(e) {
    res.status(500).json({error: 'Failed to fetch logs'});
  }
});

// Clear logs
router.delete('/logs', authenticateClient, async (req, res) => {
    try {
        // Capped collections can't be cleared easily, but we can drop/recreate or just ignore.
        // Actually capped collections cannot remove documents.
        // We will just return a message saying it's auto-managed.
        res.json({ message: 'Logs are auto-rotated (Capped Collection)' });
    } catch(e) {
        res.status(500).json({ error: 'Error' });
    }
});

module.exports = router;

