}

export interface Domain {
  _id: string;
  name: string;
  verification_token: string;
  is_verified: boolean;
  mx_status: string;
  dkim_public_key?: string;
}

export interface Mailbox {
  _id: string;
  email: string;
  domain_id: { _id: string; name: string } | string;
}

export interface EmailMessage {
  _id: string;
  from: string;
  to: string;
  subject: string;
  text_body: string;
  html_body: string;
  folder: 'inbox' | 'sent';
  created_at: string;
}

export interface DnsStatus {
  verification: boolean;
  a_record: boolean;
  mx: boolean;
  spf: boolean;
  dmarc: boolean;
  dkim: boolean;
}

declare global {
  namespace JSX {
    interface IntrinsicElements {
      [elemName: string]: any;
    }
  }
}

const dns = require('dns').promises;
const crypto = require('crypto');

/**
 * Generates a random unique verification token.
 * @returns {string} Hex string token
 */
const generateVerificationToken = () => {
  return crypto.randomBytes(32).toString('hex');
};

/**
 * Fetches TXT records for the domain and checks if the token exists.
 * @param {string} domainName 
 * @param {string} token 
 * @returns {Promise<boolean>}
 */
const verifyDomainDns = async (domainName, token) => {
  try {
    // resolveTxt returns an array of arrays (chunks of text)
    const records = await dns.resolveTxt(domainName);

    // Flatten chunks and look for the token
    const flatRecords = records.map(chunk => chunk.join(''));

    // Check if any record equals the token or contains it
    return flatRecords.some(record => record.includes(token));
  } catch (error) {
    // Domain not found or no TXT records
    return false;
  }
};

/**
 * Fetches MX records to see if they exist.
 * Checks for actual MX records on the domain.
 * @param {string} domainName 
 * @returns {Promise<boolean>}
 */
const checkMxRecord = async (domainName) => {
  try {
    const records = await dns.resolveMx(domainName);
    return records && records.length > 0;
  } catch (error) {
    return false;
  }
};

/**
 * Generates RSA 2048-bit key pair for DKIM.
 * @returns {{privateKey: string, publicKey: string}}
 */
const generateDkimKeys = () => {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem'
    }
  });

  return { privateKey, publicKey };
};

/**
 * Checks detailed status of all required DNS records
 * @param {string} domainName
 * @param {string} token
 */
const getDnsStatus = async (domainName, token) => {
  const status = {
    verification: false,
    a_record: false,
    mx: false,
    spf: false,
    dmarc: false,
    dkim: false
  };

  try {
    // 1. Root TXT (Verification & SPF)
    // We catch errors individually to allow partial success
    let txtRecords = [];
    try {
      txtRecords = await dns.resolveTxt(domainName);
    } catch (e) { /* ignore */ }

    const flatTxt = txtRecords.map(c => c.join(''));
    status.verification = flatTxt.some(r => r.includes(token));
    status.spf = flatTxt.some(r => r.toLowerCase().includes('v=spf1'));

    // 2. A Record (mail.domain)
    try {
      const aRecords = await dns.resolve4(`mail.${domainName}`);
      status.a_record = aRecords.length > 0;
    } catch (e) { /* ignore */ }

    // 3. MX Record
    try {
      const mxRecords = await dns.resolveMx(domainName);
      // Valid if MX records exist. Ideally should point to mail.domainName
      // We check if any exchange contains 'mail.' or matches the A-record host
      status.mx = mxRecords.length > 0 && mxRecords.some(r => r.exchange && r.exchange.includes('mail.'));
    } catch (e) { /* ignore */ }

    // 4. DMARC (_dmarc.domain)
    try {
      const dmarcRecords = await dns.resolveTxt(`_dmarc.${domainName}`);
      const flatDmarc = dmarcRecords.map(c => c.join(''));
      status.dmarc = flatDmarc.some(r => r.toLowerCase().includes('v=dmarc1'));
    } catch (e) { /* ignore */ }

    // 5. DKIM (default._domainkey.domain)
    try {
      const dkimRecords = await dns.resolveTxt(`default._domainkey.${domainName}`);
      const flatDkim = dkimRecords.map(c => c.join(''));
      status.dkim = flatDkim.some(r => r.includes('v=DKIM1'));
    } catch (e) { /* ignore */ }

  } catch (err) {
    // Global failure
  }

  return status;
};

module.exports = {
  generateVerificationToken,
  verifyDomainDns,
  checkMxRecord,
  generateDkimKeys,
  getDnsStatus
};

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const dns = require('dns').promises;
const nodemailer = require('nodemailer');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const { authenticateWebmail } = require('../middleware/auth');
const logger = require('../config/logger');

// Webmail Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
    res.json({ token, email: mailbox.email });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Webmail Messages
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const messages = await EmailMessage.find({ mailbox_id: req.user.mailbox_id })
      .sort({ created_at: -1 })
      .limit(100);
    res.json(messages);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// Helper: Send email to external server
const deliverExternal = async (senderEmail, recipientEmail, subject, text, html) => {
  try {
    const domainPart = recipientEmail.split('@')[1];
    if (!domainPart) throw new Error('Invalid recipient domain');

    // 1. Resolve MX Records
    const mxRecords = await dns.resolveMx(domainPart);
    if (!mxRecords || mxRecords.length === 0) throw new Error('No MX records found for domain');

    // Sort by priority (lowest number first)
    const bestMx = mxRecords.sort((a, b) => a.priority - b.priority)[0].exchange;

    logger.info(`Resolving delivery for ${recipientEmail}: via ${bestMx}`);

    // 2. Prepare DKIM Signing
    // Fetch sender mailbox and domain to get private key
    const senderMailbox = await Mailbox.findOne({ email: senderEmail }).populate('domain_id');
    let dkimOptions = undefined;

    if (senderMailbox && senderMailbox.domain_id && senderMailbox.domain_id.dkim_private_key) {
      dkimOptions = {
        domainName: senderMailbox.domain_id.name,
        keySelector: 'default', // We default to 'default' selector
        privateKey: senderMailbox.domain_id.dkim_private_key
      };
      logger.info(`DKIM Signing enabled for ${senderEmail}`);
    } else {
      logger.warn(`No DKIM key found for ${senderEmail}. Email will be unsigned.`);
    }

    // 3. Create Transporter
    const transporter = nodemailer.createTransport({
      host: bestMx,
      port: 25, // Standard MTA-to-MTA port
      secure: false, // TLS is upgraded via STARTTLS usually
      tls: {
        rejectUnauthorized: false // Often necessary for opportunistic TLS
      },
      name: process.env.MY_HOSTNAME || 'smtp-server.local', // HELO hostname
      dkim: dkimOptions
    });

    // 4. Send
    await transporter.sendMail({
      from: senderEmail,
      to: recipientEmail,
      subject: subject,
      text: text,
      html: html
    });

    logger.info(`External Delivery Success: ${recipientEmail}`);
    return true;
  } catch (error) {
    logger.error(`External Delivery Failed to ${recipientEmail}: ${error.message}`);
    return false;
  }
};

// Send Email
router.post('/send', authenticateWebmail, async (req, res) => {
  try {
    const { to, subject, body } = req.body;

    if (!to) return res.status(400).json({ error: 'Recipient required' });

    const senderMailboxId = req.user.mailbox_id;
    const senderEmail = req.user.email;

    // 1. Save to Sender's Sent Folder
    const htmlContent = body ? body.replace(/\n/g, '<br>') : '';
    const safeHtml = `<div style="font-family: sans-serif;">${htmlContent}</div>`;

    await EmailMessage.create({
      mailbox_id: senderMailboxId,
      direction: 'outbound',
      from: senderEmail,
      to,
      subject: subject || '',
      text_body: body || '',
      html_body: safeHtml,
      folder: 'sent',
      is_read: true
    });

    // 2. Process Delivery
    const recipients = to.split(/[;,]+/).map(r => r.trim()).filter(r => r);

    for (const recipientEmail of recipients) {
      // Check if local
      const recipientMailbox = await Mailbox.findOne({ email: recipientEmail });

      if (recipientMailbox) {
        // --- LOCAL DELIVERY ---
        await EmailMessage.create({
          mailbox_id: recipientMailbox._id,
          direction: 'inbound',
          from: senderEmail,
          to: recipientEmail,
          subject: subject || '',
          text_body: body || '',
          html_body: safeHtml,
          folder: 'inbox',
          is_read: false
        });
        logger.info(`Internal Delivery: ${senderEmail} -> ${recipientEmail}`);
      } else {
        // --- EXTERNAL DELIVERY ---
        // Fire and forget (don't block the API response, but log errors)
        deliverExternal(senderEmail, recipientEmail, subject, body, safeHtml);
      }
    }

    res.json({ message: 'Email sent successfully' });
  } catch (err) {
    logger.error('Send Error:', err);
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = router;

