            {/* Add Mailbox Form */}
            {props.selectedDomainId === domain._id && (
              <div className="mt-4 border-t border-gray-100 pt-4 bg-gray-50/50 -mx-4 sm:-mx-5 px-4 sm:px-5 pb-1 rounded-b-xl">
